import pandas as pd, numpy as np, re
from pathlib import Path

path=Path('/root/environment/data/ckd_lab_data.csv')
df=pd.read_csv(path, dtype=str)

# normalize numeric strings

def normalize_num(x):
    if pd.isna(x):
        return np.nan
    s=str(x).strip()
    if s=='' or s.lower() in {'na','nan','null','none'}:
        return np.nan
    # remove spaces
    s=s.replace(' ','')
    # if comma and dot both, assume comma thousand separator
    if ',' in s and '.' in s:
        s=s.replace(',','')
    elif ',' in s:
        # treat comma as decimal separator
        s=s.replace(',','.')
    # handle leading +
    try:
        return float(s)
    except Exception:
        # try scientific with uppercase E maybe? float handles
        try:
            return float(re.sub(r'[^0-9eE+\-\.]','',s))
        except Exception:
            return np.nan

num_df=df.copy()
for c in num_df.columns:
    num_df[c]=num_df[c].map(normalize_num)

print('rows',len(num_df))
print('nan rows',num_df.isna().any(axis=1).sum())

# show min/max for each col ignoring nan
stats=num_df.describe().T[['min','max','mean']]
print(stats.head(10))

# show columns with extreme max >1000
print('cols max>1000',stats[stats['max']>1000].index.tolist())
